    reg reset;
    wire [4:0] q;

    // Instantiate DUT
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation
    always #5 clk = ~clk;

    integer errors = 0;
    integer cycle_count = 0;
    reg [4:0] expected_q;

    // Function to compute expected next state for a Galois LFSR (5-bit, taps at 5 and 3, which are indices 4 and 2 if 0-indexed)
    // Wait, let's examine standard 5-bit maximal length Galois LFSR with taps at 5 and 3.
    // Usually, bits are q[4:0] (5 bits). Taps at 5 and 3 mean feedback polynomial x^5 + x^3 + 1.
    // In standard Galois configuration:
    // next_q[0] = q[4] (feedback from bit 4)
    // next_q[1] = q[0]
    // next_q[2] = q[1] ^ q[4] (tap at 3, which is index 2)
    // next_q[3] = q[2]
    // next_q[4] = q[3] ^ q[4] (tap at 5, which is index 4)
    // Let's check what the candidate RTL implements:
    // q <= {q[3] ^ q[4], q[4], q[2:0]};
    // This gives:
    // q[4]_next = q[3] ^ q[4]
    // q[3]_next = q[4]
    // q[2]_next = q[2] ... wait! q[2:0] means q[2], q[1], q[0] are just shifted or assigned?
    // Let's look closely at {q[3] ^ q[4], q[4], q[2:0]}:
    // Resulting vector:
    // bit 4: q[3] ^ q[4]
    // bit 3: q[4]
    // bit 2: q[2]
    // bit 1: q[1]
    // bit 0: q[0]
    // Notice that q[2], q[1], q[0] just shift or stay? No, {q[3] ^ q[4], q[4], q[2:0]} has 5 bits:
    // [4] -> q[3] ^ q[4]
    // [3] -> q[4]
    // [2:0] -> q[2], q[1], q[0]
    // This means q[2], q[1], q[0] do NOT shift from lower bits! q[2] stays q[2], q[1] stays q[1], q[0] stays q[0]!
    // That is a classic off-by-one / wiring bug in the candidate RTL!

    initial begin
        clk = 0;
        reset = 1;

        #12;
        // Check reset state
        if (q !== 5'b00001) begin
            $display("ERROR: Reset state incorrect. Expected 00001, got %b", q);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        // Trace a few cycles to expose the bug
        // At reset, q = 00001.
        // Let's see what DUT computes for q after 1 clock:
        // q = 00001 -> q[4]=0, q[3]=0, q[2]=0, q[1]=0, q[0]=1
        // Candidate: {q[3]^q[4], q[4], q[2:0]} = {0^0, 0, 0, 0, 1} = 00001!
        // The LFSR is stuck at 00001 because q[2:0] doesn't shift bits down (should be q[3:1] or similar)!

        repeat (10) begin
            @(posedge clk);
            #1;
            cycle_count = cycle_count + 1;
            $display("Cycle %0d: q = %b", cycle_count, q);
        end

        // A proper maximal LFSR should change state every cycle. If q remains 5'b00001, it's broken.
        if (q === 5'b00001) begin
            $display("ERROR: LFSR is stuck (did not shift/progress from reset value).");
            errors = errors + 1;
        end

        if (errors > 0) begin
            $display("*** TEST RESULT: FAIL ***");
        end else begin
            $display("*** TEST RESULT: PASS ***");
        end
        $finish;
    end

endmodule
